mapper.update:
update user
real_name = #{realName}, phone = #{phone}, email = #{email}, gender = #{gender}, school = #{school}, faculty = #{faculty}, professional = #{professional}, grade = #{grade}, class_num = #{classNum}, subject = #{subject},
where id = #{id}

mapper.select:
select id, real_name, phone, email, role, school, faculty, professional, grade, class_num, subject, gender, image_address, register_time from user where role = #{role}
and ( real_name LIKE CONCAT('%', #{content}, '%') or phone LIKE CONCAT('%', #{content}, '%') or email LIKE CONCAT('%', #{content}, '%') or school LIKE CONCAT('%', #{content}, '%') or faculty LIKE CONCAT('%', #{content}, '%') or professional LIKE CONCAT('%', #{content}, '%') or subject LIKE CONCAT('%', #{content}, '%') or gender LIKE CONCAT('%', #{content}, '%') )
order by id asc -- asc相反为升序
